function calcPrice(c) {
  const disc = c.copies >= 500 ? 0.92 : c.copies >= 300 ? 0.95 : 1;
  const paper = c.pages * PAPER[c.paper] * disc;
  const fin = c.finishing.reduce((a, f) => a + FINISH[f], 0);
  const variable = paper + COVER[c.cover] + fin;
  const photo = c.photoDays * 3500000, design = c.pages * 85000, setup = 4000000;
  const fixed = photo + design + setup;
  const hpp = variable + fixed / c.copies;
  const sell = Math.ceil(hpp / (1 - c.margin / 100) / 5000) * 5000;
  return {paper, cover: COVER[c.cover], fin, photo, design, setup, variable, fixed, hpp, sell, total: sell * c.copies, profit: (sell - hpp) * c.copies, bep: Math.ceil(fixed / Math.max(1, sell - variable))};
}

